  const { result } = renderHook(() => useAsyncState(() => Promise.resolve('hello')));
  expect(result.current.loading).toBe(false);
  expect(result.current.data).toBeUndefined();
});

test('sets loading true while pending', async () => {
  let resolve: (v: string) => void;
  const promise = new Promise<string>(r => { resolve = r; });
  const { result } = renderHook(() => useAsyncState(() => promise));
  act(() => { result.current.execute(); });
  expect(result.current.loading).toBe(true);
  await act(async () => { resolve!('done'); await promise; });
});

test('sets data on resolve', async () => {
  const { result } = renderHook(() => useAsyncState(() => Promise.resolve(42)));
  await act(async () => { await result.current.execute(); });
  expect(result.current.data).toBe(42);
  expect(result.current.loading).toBe(false);
});

